<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sorting Visualizer</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090d18;
      --panel: #12192a;
      --text: #edf2ff;
      --muted: #929db5;
      --accent: #7c8cff;
      --accent-light: #5eead4;
      --danger: #fb7185;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      overflow-x: hidden;
      font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at 50% 0%, #172344 0, transparent 40%),
        var(--bg);
    }

    main {
      width: min(960px, 100%);
      padding: clamp(20px, 4vw, 40px);
      border: 1px solid #25304a;
      border-radius: 22px;
      background: rgba(18, 25, 42, 0.92);
      box-shadow: 0 24px 80px #0008;
    }

    header {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 20px;
      margin-bottom: 24px;
    }

    h1 {
      margin: 0 0 6px;
      font-size: clamp(1.65rem, 4vw, 2.5rem);
      letter-spacing: -0.04em;
    }

    p {
      margin: 0;
      color: var(--muted);
    }

    .controls {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
    }

    button {
      min-width: 92px;
      padding: 11px 16px;
      border: 1px solid #35415d;
      border-radius: 10px;
      color: var(--text);
      background: #1b2438;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 120ms ease, border-color 120ms ease,
                  background 120ms ease;
    }

    button:hover:not(:disabled) {
      transform: translateY(-2px);
      border-color: #6473a1;
      background: #242f49;
    }

    button:focus-visible {
      outline: 3px solid #7c8cff66;
      outline-offset: 2px;
    }

    button:disabled {
      cursor: not-allowed;
      opacity: 0.55;
    }

    #sort {
      border-color: #8290ff;
      background: var(--accent);
      color: #090d18;
    }

    #bars {
      height: clamp(300px, 55vh, 520px);
      display: flex;
      align-items: flex-end;
      justify-content: center;
      gap: clamp(2px, 0.55vw, 7px);
      padding: 18px 18px 0;
      overflow: hidden;
      border: 1px solid #283450;
      border-radius: 16px;
      background:
        linear-gradient(#ffffff08 1px, transparent 1px),
        #0c1220;
      background-size: 100% 25%;
    }

    .bar {
      flex: 1 1 0;
      min-width: 2px;
      max-width: 46px;
      height: 1%;
      border-radius: 6px 6px 2px 2px;
      background: linear-gradient(to top, var(--accent), var(--accent-light));
      box-shadow: 0 0 14px #7c8cff35;
      transition: height 110ms ease, background 110ms ease,
                  transform 110ms ease;
    }

    .bar.active {
      z-index: 1;
      transform: translateY(-3px);
      background: linear-gradient(to top, var(--danger), #fbbf24);
      box-shadow: 0 0 18px #fb718566;
    }

    .bar.done {
      background: linear-gradient(to top, #22c55e, #86efac);
    }

    @media (max-width: 650px) {
      header { align-items: stretch; flex-direction: column; }
      .controls button { flex: 1; }
    }

    @media (prefers-reduced-motion: reduce) {
      .bar, button { transition: none; }
    }
  </style>
</head>
<body>
  <main>
    <header>
      <div>
        <h1>Sorting Visualizer</h1>
        <p>Bubble sort, one comparison at a time.</p>
      </div>
      <div class="controls">
        <button id="sort" type="button">Sort</button>
        <button id="shuffle" type="button">Shuffle</button>
        <button id="reset" type="button">Reset</button>
      </div>
    </header>
    <div id="bars" aria-label="Array visualization"></div>
  </main>

  <script>
    (() => {
      "use strict";

      const initial = [
        38, 72, 19, 91, 47, 64, 12, 83, 55, 29,
        97, 42, 68, 24, 76, 8, 59, 34, 88, 51
      ];

      const bars = document.getElementById("bars");
      const sortButton = document.getElementById("sort");
      const shuffleButton = document.getElementById("shuffle");
      const resetButton = document.getElementById("reset");

      let values = initial.slice();
      let index = 0;
      let end = Math.max(0, values.length - 1);
      let animationId = null;
      let active = [];

      function sorted() {
        for (let i = 1; i < values.length; i++) {
          if (values[i - 1] > values[i]) return false;
        }
        return true;
      }

      function resetSortState() {
        index = 0;
        end = Math.max(0, values.length - 1);
        active = [];
      }

      function render() {
        bars.replaceChildren();
        const max = Math.max(1, ...values.map(value => Math.abs(value)));

        values.forEach((value, i) => {
          const bar = document.createElement("div");
          bar.className = "bar";
          if (active.includes(i)) bar.classList.add("active");
          if (sorted()) bar.classList.add("done");
          bar.style.height = `${Math.max(1, Math.abs(value) / max * 100)}%`;
          bar.title = String(value);
          bar.setAttribute("aria-label", String(value));
          bars.appendChild(bar);
        });
      }

      function stopAnimation() {
        if (animationId !== null) cancelAnimationFrame(animationId);
        animationId = null;
        sortButton.disabled = false;
      }

      function sortStep() {
        if (values.length < 2 || sorted()) {
          active = [];
          render();
          return true;
        }

        if (end < 1) {
          active = [];
          render();
          return true;
        }

        active = [index, index + 1];

        if (values[index] > values[index + 1]) {
          const temp = values[index];
          values[index] = values[index + 1];
          values[index + 1] = temp;
        }

        index++;
        if (index >= end) {
          index = 0;
          end--;
        }

        const complete = sorted();
        if (complete) active = [];
        render();
        return complete;
      }

      function animateSort() {
        if (animationId !== null) return;
        sortButton.disabled = true;
        let previous = 0;

        function frame(time) {
          if (time - previous >= 80) {
            previous = time;
            if (sortStep()) {
              stopAnimation();
              return;
            }
          }
          animationId = requestAnimationFrame(frame);
        }

        animationId = requestAnimationFrame(frame);
      }

      function setArray(array) {
        stopAnimation();
        if (!Array.isArray(array)) {
          throw new TypeError("setArray expects an array");
        }
        values = array.map(Number);
        if (values.some(value => !Number.isFinite(value))) {
          throw new TypeError("Array values must be finite numbers");
        }
        resetSortState();
        render();
      }

      function shuffle() {
        stopAnimation();
        for (let i = values.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [values[i], values[j]] = [values[j], values[i]];
        }
        resetSortState();
        render();
      }

      sortButton.addEventListener("click", animateSort);
      shuffleButton.addEventListener("click", shuffle);
      resetButton.addEventListener("click", () => setArray(initial));

      window.viz = {
        array: () => values.slice(),
        setArray,
        sortStep,
        sorted
      };

      render();
    })();
  </script>
</body>
</html>
